/** Trusted Native/Study composition; callers supply validated answers, never actions. */
trait LogicalRuntime {
    private function logicalAssignmentEntry(array $assignment,array $binding): array {
        $parent=$this->store->db->row($this->store->prepare('SELECT checkpoint_json FROM '.$this->store->db->table('study_executions').' WHERE id=%s FOR UPDATE',$binding['execution_id']));if(!$parent)return $assignment;
        $state=P\Database::json($parent['checkpoint_json'])['context']['logical_state']??array();$nav=$state['navigation']??null;if(!$nav||($nav['target_execution_id']??null)!==$binding['block_execution_id'])return $assignment;
        $row=$this->store->find('executions',$assignment['execution_id'],true);$current=json_decode($row['binding_json'],true);if(($current['logical_entry_condition']??null)===$nav['condition_id'])return $assignment;
        $current['logical_entry_condition']=$nav['condition_id'];$current['logical_entry_page']=$nav['entry_page'];$current['logical_entry_question']=$nav['question_id'];$current['logical_skipped_ids']=array_keys(array_filter($state['question_states'][$nav['target_id']]??array(),static function($s){return $s==='skipped_by_logic';}));$updates=array('binding_json'=>D::json($current),'page_index'=>$nav['entry_page']);
        if($row['partial_json']!==null){$partial=json_decode($row['partial_json'],true);$partial['page']=$nav['entry_page'];$updates['partial_json']=D::json($partial);}$this->store->update('executions',$updates,$this->store->prepare('id=%s',$row['id']));return $assignment;
    }
    private function logicalReach(array $e,array $d): array {
        $old=$this->randomization($e);if(($old['contract']??null)!=='LOCAL_RANDOMIZATION_LAZY_V3')return $e;
        $binding=json_decode($e['binding_json'],true);$controls=array();$plans=array();if(isset($binding['execution_id'],$binding['block_execution_id'])){$parent=$this->store->db->row($this->store->prepare('SELECT checkpoint_json FROM '.$this->store->db->table('study_executions').' WHERE id=%s FOR UPDATE',$binding['execution_id']));$block=$this->store->db->row($this->store->prepare('SELECT definition_id FROM '.$this->store->db->table('block_executions').' WHERE id=%s',$binding['block_execution_id']));$checkpoint=$parent?P\Database::json($parent['checkpoint_json']):array();$plans=$checkpoint['context']['logical_state']['native_plans'][$binding['block_execution_id']]??array();foreach($checkpoint['context']['logical_state']['random_controls']??array() as $key=>$control){$prefix=$block['definition_id'].'|';if(strpos($key,$prefix)===0)$controls[substr($key,strlen($prefix))]=$control;}}
        $record=Randomization::reach($d,$old,(int)$e['page_index'],$this->now()*1000,$controls,(int)($binding['logical_entry_page']??0),$plans);$updates=array();
        if(D::json($record)!==D::json($old)){$meta=$e['metadata_json']===null?array():json_decode($e['metadata_json'],true);$meta['randomization']=$record;$updates['metadata_json']=D::json($meta);if($e['partial_json']!==null){$session=json_decode($e['partial_json'],true);$session['metadata']['randomization']=$record;$updates['partial_json']=D::json($session);}}
        if($plans&&D::json($record)!==D::json($old)&&$e['partial_json']!==null){
            $keys=$this->logicalResponseKeys(Randomization::apply($d,$record));$partial=json_decode($updates['partial_json']??$e['partial_json'],true);$partial['answers']=array_intersect_key($partial['answers'],array_flip($keys));$partial['touched']=array_intersect_key($partial['touched']??array(),array_flip($keys));$updates['partial_json']=D::json($partial);
        }
        if(!empty($binding['logical_entry_question'])){$ids=array();$walk=function($items)use(&$walk,&$ids){foreach($items as $item){if($item['response_key'])$ids[]=$item['id'];if($item['type']==='matrix')foreach($item['properties']['matrix_rows'] as $row)$ids[]=$row['id'];$walk($item['children']);}};$walk(Randomization::apply($d,$record)['elements']);$position=array_search($binding['logical_entry_question'],$ids,true);if($position===false)throw new P\IntegrityFailure('LOGICAL_ENTRY_NOT_SELECTED');$priorPageIds=array();$page=0;$scan=function($items)use(&$scan,&$priorPageIds,&$page,$binding){foreach($items as $item){if($item['type']==='page_break'){$page++;continue;}if($page<(int)($binding['logical_entry_page']??0)){if($item['response_key'])$priorPageIds[]=$item['id'];if($item['type']==='matrix')foreach($item['properties']['matrix_rows'] as $row)$priorPageIds[]=$row['id'];}$scan($item['children']);}};$scan($d['elements']);$binding['logical_skipped_ids']=array_values(array_unique(array_merge($priorPageIds,array_slice($ids,0,$position))));if(D::json($binding)!==$e['binding_json'])$updates['binding_json']=D::json($binding);}
        if(isset($updates['metadata_json']))\EIPSI\StudyEngine\Management\Audit::native($binding,$e['id'],'randomization',(int)$e['revision'],$record);if($updates)$this->store->update('executions',$updates,$this->store->prepare('id=%s',$e['id']));return array_replace($e,$updates);
    }
    private function logicalResponseKeys(array $d): array {$keys=array();$walk=function($items)use(&$walk,&$keys){foreach($items as $e){if(!empty($e['response_key']))$keys[]=$e['response_key'];if($e['type']==='matrix')foreach($e['properties']['matrix_rows'] as $row)$keys[]=$row['response_key'];$walk($e['children']);}};$walk($d['elements']);return $keys;}
    private function logicalTarget(array $logical,array $source): ?string {
        $nav=$logical['navigation'];if(!$nav||!in_array($nav['type'],array('JUMP','GO_QUESTION'),true)||$nav['target_execution_id']===json_decode($source['binding_json'],true)['block_execution_id'])return null;
        $node=null;foreach($logical['protocol']['nodes'] as $n)if($n['id']===$nav['target_id'])$node=$n;if(!$node||empty($node['metadata']['native_version_id']))throw new P\IntegrityFailure('NATIVE_LOGICAL_TARGET_REQUIRED');
        $binding=$logical['binding'];foreach(array('logical_skipped_ids','response_discarded','logical_entry_page','logical_transition_exit','logical_target_execution_id','logical_entry_question','logical_entry_condition') as $key)unset($binding[$key]);$binding['block_execution_id']=$nav['target_execution_id'];
        return $this->store->db->joinNativeTransaction(function()use($node,$binding,$nav,$logical){
            $assignment=$this->studyAssignment($node['metadata']['native_version_id'],$binding);$id=$assignment['execution_id'];$row=$this->store->find('executions',$id,true);$binding=json_decode($row['binding_json'],true);
            $binding['logical_skipped_ids']=array_keys(array_filter($logical['state']['question_states'][$nav['target_id']]??array(),static function($v){return $v==='skipped_by_logic';}));$binding['logical_entry_page']=$nav['entry_page'];$binding['logical_entry_question']=$nav['question_id'];
            $this->store->update('executions',array('binding_json'=>D::json($binding),'page_index'=>$nav['entry_page']),$this->store->prepare('id=%s',$id));return $id;
        });
    }
    private function logicalResult(string $id): array {$seen=array();for($hop=0;$hop<32;$hop++){if(isset($seen[$id]))throw new P\IntegrityFailure('LOGICAL_RECOVERY_CYCLE');$seen[$id]=true;list($e,$v,$d)=$this->checked($id);$binding=json_decode($e['binding_json'],true);if($e['state']==='LOGICAL_EXIT'&&!empty($binding['logical_target_execution_id'])){$id=$binding['logical_target_execution_id'];continue;}$this->expire($e);return $this->frame($e,$v,$d);}throw new P\IntegrityFailure('LOGICAL_RECOVERY_DEPTH');}
    private function logicalProtocol(array $binding): ?array {
        if(!isset($binding['block_execution_id']))return null;$v=(new P\StudyVersionRepository($this->store->db))->find($binding['study_version_id']);if(!$v)return null;$d=P\Database::json($v['protocol_json']);return empty($d['protocol_metadata']['trajectory_conditions'])&&($d['protocol_metadata']['execution_planning']??null)!=='DEPENDENCY_PLAN_V1'?null:$d;
    }
    private function logicalDefinition(array $d,array $binding): array {
        $skipped=$binding['logical_skipped_ids']??array();if(!$skipped)return $d;
        $walk=function(&$items)use(&$walk,$skipped){foreach($items as &$e){if(in_array($e['id'],$skipped,true)){if(isset($e['properties']['required']))$e['properties']['required']=false;if($e['type']==='multiple_choice')$e['properties']['min_selected']=0;}if($e['type']==='matrix')foreach($e['properties']['matrix_rows'] as &$row)if(in_array($row['id'],$skipped,true))$row['required']=false;unset($row);$walk($e['children']);}unset($e);};$walk($d['elements']);return $d;
    }
    private function logicalCommand(array $e,array $d,array $request): ?array {
        $binding=json_decode($e['binding_json'],true);$protocol=$this->logicalProtocol($binding);if(!$protocol||!in_array($request['action'],array('logic','next','submit','partial'),true))return null;
        require_once dirname(__DIR__,2).'/study-engine/persistence.php';
        $config=\EIPSI\StudyEngine\Configuration\KeyringResolver::binary('seed',true);$keys=$config['keys'];
        $owner=new \EIPSI\StudyEngine\Orchestration\ExecutionOwner($this->store->db,new P\SeedVault($keys,$config['current']));
        return $this->store->db->joinNativeTransaction(function()use($owner,$binding,$protocol,$e,$d,$request){return $owner->joinNative(function($owner)use($binding,$protocol,$e,$d,$request){
            $view=$owner->view($binding['execution_id']);if(!isset($view['revision']))throw new P\IntegrityFailure('LOGICAL_CHECKPOINT_UNAVAILABLE');$block=$view['snapshot']['instances'][$binding['block_execution_id']]??null;if(!$block)throw new P\IntegrityFailure('LOGICAL_BLOCK_UNAVAILABLE');
            $node=null;foreach($protocol['nodes'] as $n)if($n['id']===$block['definition_id'])$node=$n;$old=$e['partial_json']===null?array():json_decode($e['partial_json'],true)['answers'];$answers=array();$states=array();$changed=array();$presence=array();
            $selected=array();$walk=function($items)use(&$walk,&$selected){foreach($items as $item){$selected[$item['id']]=true;if($item['type']==='matrix')foreach($item['properties']['matrix_rows'] as $r)$selected[$r['id']]=true;$walk($item['children']);}};$walk(Randomization::apply($d,$this->randomization($e))['elements']);
            foreach($node['metadata']['native_questions']??array() as $q){$key=$q['response_key'];$present=array_key_exists($key,$request['answers']);$answered=$present&&$request['answers'][$key]!==null&&$request['answers'][$key]!==''&&$request['answers'][$key]!==array();
                $excluded=false;foreach($q['randomization_path']??array() as $path){$r=$this->randomization($e)['blocks'][$path['randomization_id']]??null;if($r&&!in_array($path['candidate_id'],$r['order'],true))$excluded=true;}$unresolved=!$excluded&&$q['randomization_id']!==null&&($this->randomization($e)['contract']??null)==='LOCAL_RANDOMIZATION_LAZY_V3'&&!isset($this->randomization($e)['blocks'][$q['randomization_id']]);$states[$q['id']]=in_array($q['id'],$binding['logical_skipped_ids']??array(),true)?'skipped_by_logic':($unresolved?'not_reached':(!isset($selected[$q['id']])?'not_selected_by_randomization':($answered?'answered':($q['page']>(int)$e['page_index']?'not_reached':'unanswered'))));
                $presence[$q['id']]=array('selected'=>$unresolved?null:isset($selected[$q['id']]),'shown'=>isset($request['metadata']['items'][$key]['presented_at'])||(!$unresolved&&isset($selected[$q['id']])&&!in_array($q['id'],$binding['logical_skipped_ids']??array(),true)&&$q['page']===(int)$e['page_index']));
                if($answered)$answers[$q['id']]=$request['answers'][$key];if(D::json(array($old[$key]??null))!==D::json(array($request['answers'][$key]??null)))$changed[]=$q['id'];
            }
            $nativeRecords=array();$instances=$view['snapshot']['instances'];foreach($this->store->db->rows($this->store->prepare('SELECT binding_json,metadata_json FROM '.$this->store->table('executions')." WHERE state IN ('ACTIVE','SESSION_EXPIRED','COMPLETED','LOGICAL_EXIT') AND JSON_UNQUOTE(JSON_EXTRACT(binding_json,'$.execution_id'))=%s ORDER BY created_at,id FOR UPDATE",$binding['execution_id'])) as $nativeRow){$b=json_decode($nativeRow['binding_json'],true);$definition=$instances[$b['block_execution_id']??'']['definition_id']??null;if($definition){$current=$view['snapshot']['logical_trajectory']['current_occurrence'][$definition]??null;if($current===null||$current===($b['block_execution_id']??null))$nativeRecords[$definition]=json_decode($nativeRow['metadata_json']??'{}',true)['randomization']??array();}}
            $nativeRecords[$block['definition_id']]=json_decode($e['metadata_json']??'{}',true)['randomization']??array();
            $events=$request['action']==='submit'?array('ANSWER','COMPLETE'):array('ANSWER');
            foreach($events as $event){$result=$owner->dispatch($binding['execution_id'],array('id'=>'LC_'.substr(hash('sha256',$e['id'].'|'.$request['command_id'].'|'.$event),0,40),'kind'=>'NATIVE_LOGIC','expected_revision'=>$view['revision'],'data'=>array('block_execution_id'=>$binding['block_execution_id'],'transition_id'=>$request['command_id'].'|'.$event,'answers'=>$answers,'question_states'=>$states,'native_randomizations'=>$nativeRecords,'question_presence'=>$presence,'changed_questions'=>$event==='COMPLETE'?array_keys($states):$changed,'event'=>$event)),array(),null,true);if(!isset($result['revision']))throw new P\IntegrityFailure('LOGICAL_TRANSITION_FAILED');$view=$owner->view($binding['execution_id']);if(($view['snapshot']['logical_trajectory']['navigation']['transition_id']??null)===$request['command_id'].'|'.$event)break;}
            $logical=$view['snapshot']['logical_trajectory'];$nav=$logical['navigation'];$skip=array_keys(array_filter($logical['question_states'][$block['definition_id']]??array(),static function($status){return $status==='skipped_by_logic';}));
            $binding['logical_skipped_ids']=$skip;
            $this->store->update('executions',array('binding_json'=>D::json($binding)),$this->store->prepare('id=%s',$e['id']));
            $planned=($protocol['protocol_metadata']['execution_planning']??null)==='DEPENDENCY_PLAN_V1';$updated=$planned?$this->logicalReach($e,$d):$e;$activeKeys=$this->logicalResponseKeys(Randomization::apply($d,$this->randomization($updated)));
            return array('navigation'=>$nav&&strpos($nav['transition_id']??'', $request['command_id'].'|')===0&&($nav['source_execution_id']??null)===$block['id']?$nav:null,'binding'=>$binding,'state'=>$logical,'view'=>$view,'protocol'=>$protocol)+($planned?array('native_execution'=>$updated,'active_response_keys'=>$activeKeys):array());
        });});
    }
}
